import React, { useState } from 'react';
import {
  Button,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  FormControl,
  InputLabel,
  MenuItem,
  Select,
  TextField,
} from '@mui/material';

export type MsmeRegistryStatus = 'pending' | 'verified' | 'flagged' | 'suspended';

interface MSMEStatusUpdateDialogProps {
  open: boolean;
  currentStatus: string;
  companyName: string;
  saving: boolean;
  onClose: () => void;
  onConfirm: (status: MsmeRegistryStatus, note: string) => void;
}

const STATUS_OPTIONS: Array<{ value: MsmeRegistryStatus; label: string }> = [
  { value: 'pending', label: 'Pending' },
  { value: 'verified', label: 'Verified' },
  { value: 'flagged', label: 'Flagged' },
  { value: 'suspended', label: 'Suspended' },
];

const MSMEStatusUpdateDialog: React.FC<MSMEStatusUpdateDialogProps> = ({
  open,
  currentStatus,
  companyName,
  saving,
  onClose,
  onConfirm,
}) => {
  const [status, setStatus] = useState<MsmeRegistryStatus>(
    (currentStatus as MsmeRegistryStatus) || 'pending',
  );
  const [note, setNote] = useState('');

  const handleConfirm = () => {
    onConfirm(status, note.trim());
  };

  return (
    <Dialog open={open} onClose={saving ? undefined : onClose} fullWidth maxWidth="sm">
      <DialogTitle>Update registry status</DialogTitle>
      <DialogContent sx={{ display: 'flex', flexDirection: 'column', gap: 2, pt: 1 }}>
        <FormControl fullWidth>
          <InputLabel id="msme-status-label">Status</InputLabel>
          <Select
            labelId="msme-status-label"
            label="Status"
            value={status}
            onChange={(event) => setStatus(event.target.value as MsmeRegistryStatus)}
          >
            {STATUS_OPTIONS.map((option) => (
              <MenuItem key={option.value} value={option.value}>
                {option.label}
              </MenuItem>
            ))}
          </Select>
        </FormControl>
        <TextField
          label="Admin note (optional)"
          value={note}
          onChange={(event) => setNote(event.target.value)}
          multiline
          minRows={3}
          placeholder={`Reason for updating ${companyName}`}
          fullWidth
        />
      </DialogContent>
      <DialogActions>
        <Button onClick={onClose} disabled={saving}>
          Cancel
        </Button>
        <Button variant="contained" onClick={handleConfirm} disabled={saving}>
          {saving ? 'Saving…' : 'Update status'}
        </Button>
      </DialogActions>
    </Dialog>
  );
};

export default MSMEStatusUpdateDialog;
