import React, { useEffect, useMemo, useState, useCallback } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import {
    Box,
    Typography,
    Paper,
    Grid,
    Button,
    Chip,
    CircularProgress,
    Alert,
    Stack,
    Table,
    TableBody,
    TableCell,
    TableContainer,
    TableHead,
    TableRow,
    TextField,
    MenuItem,
    FormControl,
    InputLabel,
    Select,
    Tab,
    Tabs,
} from '@mui/material';
import { ArrowBack, CheckCircle, Warning, Block, Flag, Download, Edit } from '@mui/icons-material';
import axios from 'axios';
import { buildApiUrl } from '../../config/apiConfig';
import AdminPortalLayout from './AdminPortalLayout';
import MSMEStatusUpdateDialog, { type MsmeRegistryStatus } from './MSMEStatusUpdateDialog';
import AuditorEvidenceWorkspace, { type EvidenceWorkspaceData } from './AuditorEvidenceWorkspace';
import { isViewRoleProfile } from '../../utils/authRole';
import { FALLBACK_PUBLIC_PRICING, TIER_DISPLAY_NAMES, resolvePlanTierKey } from '../../constants/pricingPlans';
import { exportMsmeAuditCsv } from '../../utils/msmeAuditExport';
import { useNotification } from '../../context/NotificationContext';
import { getAdminPortalUser } from '../../utils/adminPortalSession';
import FootprintStoryPanel from '../shared/FootprintStoryPanel';
import MeasurementCompletenessRing from '../shared/MeasurementCompletenessRing';
import {
  deriveMeasurementCompleteness,
  inferEnergySignals,
} from '../../utils/measurementCompleteness';

interface MSMEDetail {
    _id: string;
    companyName: string;
    companyType?: string;
    industry: string;
    businessDomain?: string;
    status: string;
    contact: {
        email: string;
        phone: string;
        address?: {
            street?: string;
            city?: string;
            state?: string;
            pincode?: string;
            country?: string;
        };
    };
    gstNumber: string;
    panNumber: string;
    establishmentYear: number;
    carbonScore?: number;
    business?: {
        numberOfEmployees?: number;
        annualTurnover?: number;
    };
    environmentalCompliance?: {
        hasEnvironmentalClearance?: boolean;
        hasPollutionControlBoard?: boolean;
        hasWasteManagement?: boolean;
    };
    createdAt: string;
    adminNotes?: Array<{
        note?: string;
        addedAt?: string;
        addedBy?: {
            profile?: {
                firstName?: string;
                lastName?: string;
            };
            email?: string;
        };
    }>;
    userId: {
        email?: string;
        isActive?: boolean;
        profile?: {
            firstName?: string;
            lastName?: string;
        };
    };
}

interface RecommendationItem {
    _id: string;
    category?: string;
    title?: string;
    priority?: 'high' | 'medium' | 'low';
    status?: string;
    potentialCO2Reduction?: number;
    createdAt?: string;
}

interface BillItem {
    _id: string;
    originalName?: string;
    fileName?: string;
    documentType?: string;
    status?: string;
    extractedData?: {
        amount?: number;
        date?: string;
    };
    createdAt?: string;
}

interface TransactionItem {
    _id: string;
    description?: string;
    category?: string;
    source?: string;
    amount?: number;
    currency?: string;
    date?: string;
    carbonFootprint?: {
        co2Emissions?: number;
    };
}

interface AdminViewData {
    carbonEmissions?: {
        totalCO2Emissions?: number;
        assessmentType?: string;
        assessmentStatus?: string;
        period?: {
            startDate?: string;
            endDate?: string;
        };
        esgScopes?: {
            scope1?: { total?: number; percentage?: number };
            scope2?: { total?: number; percentage?: number };
            scope3?: { total?: number; percentage?: number };
        };
        updatedAt?: string;
    };
    recommendations?: {
        total?: number;
        byStatus?: Record<string, number>;
        items?: RecommendationItem[];
    };
    carbonScore?: {
        current?: number;
        previous?: number | null;
        industryAverage?: number | null;
        bestInClass?: number | null;
        scoreBreakdown?: Record<string, number>;
        updatedAt?: string;
    };
    benefits?: {
        totalPoints?: number;
        level?: number;
        nextLevelPoints?: number;
        achievementsUnlocked?: number;
        carbonSaved?: number;
        streak?: number;
        recentActivities?: Array<{
            title?: string;
            description?: string;
            points?: number;
            createdAt?: string;
        }>;
    };
    profile?: {
        companyName?: string;
        companyType?: string;
        industry?: string;
        businessDomain?: string;
        establishmentYear?: number;
        contact?: MSMEDetail['contact'];
        compliance?: MSMEDetail['environmentalCompliance'];
        user?: MSMEDetail['userId'];
    };
    operations?: {
        unitsCount?: number;
        processesCount?: number;
        employeesCount?: number;
        supplyChainPartnersCount?: number;
        workflowLocked?: boolean;
        latestEstimate?: {
            totalCO2Emissions?: number;
            machineryEmissions?: number;
            rawMaterialEmissions?: number;
            packagingMaterialEmissions?: number;
            commuteEmissions?: number;
            supplyChainEmissions?: number;
            scope3Emissions?: number;
        };
        lastEstimatedAt?: string;
    };
    reporting?: {
        availableReports?: number;
        latestAssessmentDate?: string | null;
        latestReportContext?: string;
        endpoints?: Array<{
            key: string;
            label: string;
            endpoint: string;
            available: boolean;
            description: string;
        }>;
    };
    paymentSummary?: {
        currency?: string;
        paymentAmount?: number;
        factors?: {
            sector?: string;
            emissionIntensity?: number;
            transactionCount?: number;
            processCount?: number;
            rawMaterialCount?: number;
            machineryCount?: number;
            siteCount?: number;
        };
        breakdown?: {
            baseAmount?: number;
            emissionIntensityCharge?: number;
            transactionVolumeCharge?: number;
            processCharge?: number;
            rawMaterialCharge?: number;
            machineryCharge?: number;
            siteCharge?: number;
        };
        computedAt?: string;
    };
    billsUploaded?: BillItem[];
    transactionsStored?: TransactionItem[];
    evidenceWorkspace?: EvidenceWorkspaceData;
    billingPlan?: {
        selectedPlanId?: string | null;
        planInterval?: string | null;
        status?: string;
        paidUntil?: string | null;
        effectiveTier?: string;
        adminOverrideNote?: string | null;
        adminOverrideAt?: string | null;
    };
}

const ADMIN_ASSIGNABLE_PLANS = FALLBACK_PUBLIC_PRICING.fixedPlans.filter((plan) =>
    [
        'msme_free',
        'msme_starter_monthly',
        'msme_starter_yearly',
        'msme_core_monthly',
        'msme_core_yearly',
        'msme_growth_monthly',
        'msme_growth_yearly',
        'msme_scale_yearly',
    ].includes(plan.planId)
);

const formatPlanLabel = (planId?: string | null): string => {
    if (!planId) {
        return 'No plan assigned';
    }
    const plan = ADMIN_ASSIGNABLE_PLANS.find((item) => item.planId === planId);
    if (plan) {
        return `${plan.name} (${plan.interval})`;
    }
    const tier = resolvePlanTierKey(planId);
    return `${TIER_DISPLAY_NAMES[tier]} (${planId})`;
};

const formatAddress = (address?: MSMEDetail['contact']['address']) => {
    if (!address) return 'N/A';
    const parts = [
        address.street,
        address.city,
        address.state,
        address.pincode,
        address.country,
    ].filter(Boolean) as string[];
    return parts.length ? parts.join(', ') : 'N/A';
};

const formatNumber = (value: unknown, fractionDigits = 2) => {
    const numericValue = Number(value);
    if (!Number.isFinite(numericValue)) {
        return 'N/A';
    }
    return numericValue.toLocaleString('en-IN', {
        maximumFractionDigits: fractionDigits,
        minimumFractionDigits: 0,
    });
};

const formatDate = (value?: string | Date) => {
    if (!value) {
        return 'N/A';
    }
    const dateValue = new Date(value);
    if (Number.isNaN(dateValue.getTime())) {
        return 'N/A';
    }
    return dateValue.toLocaleDateString('en-IN', {
        year: 'numeric',
        month: 'short',
        day: 'numeric',
    });
};

const formatCurrency = (amount?: number, currency = 'INR') => {
    if (!Number.isFinite(Number(amount))) {
        return 'N/A';
    }
    try {
        return new Intl.NumberFormat('en-IN', {
            style: 'currency',
            currency,
            maximumFractionDigits: 0,
        }).format(Number(amount));
    } catch {
        return `₹${Number(amount).toLocaleString('en-IN')}`;
    }
};

const formatCurrencyWithFraction = (amount?: number, currency = 'INR') => {
    if (!Number.isFinite(Number(amount))) {
        return 'N/A';
    }
    try {
        return new Intl.NumberFormat('en-IN', {
            style: 'currency',
            currency,
            maximumFractionDigits: 2,
        }).format(Number(amount));
    } catch {
        return `₹${Number(amount).toLocaleString('en-IN', {
            minimumFractionDigits: 2,
            maximumFractionDigits: 2,
        })}`;
    }
};

const getPriorityColor = (priority?: string) => {
    switch (priority) {
        case 'high':
            return 'error';
        case 'medium':
            return 'warning';
        case 'low':
            return 'default';
        default:
            return 'default';
    }
};

const getRecommendationStatusColor = (status?: string) => {
    switch (status) {
        case 'completed':
            return 'success';
        case 'in_progress':
            return 'info';
        case 'dismissed':
            return 'error';
        default:
            return 'default';
    }
};

const getBooleanLabel = (value?: boolean) => (value ? 'Yes' : 'No');

const MSMEDetailView: React.FC = () => {
    const { id } = useParams<{ id: string }>();
    const navigate = useNavigate();
    const [msme, setMsme] = useState<MSMEDetail | null>(null);
    const [viewData, setViewData] = useState<AdminViewData | null>(null);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);
    const isViewRole = isViewRoleProfile();
    const portalUser = getAdminPortalUser();
    const orgType = portalUser?.accessCredentials?.organizationType;
    const preferEvidenceWorkspace = isViewRole
      || orgType === 'government_accredited_auditor'
      || orgType === 'verification_agency';
    const [detailTab, setDetailTab] = useState(preferEvidenceWorkspace ? 0 : 1);
    const { notifySuccess, notifyError } = useNotification();
    const [statusDialogOpen, setStatusDialogOpen] = useState(false);
    const [statusSaving, setStatusSaving] = useState(false);
    const [billingPlanId, setBillingPlanId] = useState('msme_scale_yearly');
    const [billingPaidUntil, setBillingPaidUntil] = useState('');
    const [billingNote, setBillingNote] = useState('');
    const [billingSaving, setBillingSaving] = useState(false);

    const getToken = () => localStorage.getItem('token');

    const fetchMSMEDetails = useCallback(async () => {
        try {
            setLoading(true);
            const response = await axios.get(
                buildApiUrl(`/admin/msme/${id}`),
                {
                    headers: { Authorization: `Bearer ${getToken()}` },
                }
            );
            setMsme(response.data?.data?.msme || null);
            setViewData(response.data?.data?.viewData || null);
        } catch (fetchError: any) {
            console.error('Error fetching MSME details:', fetchError);
            setError('Failed to load MSME details');
        } finally {
            setLoading(false);
        }
    }, [id]);

    useEffect(() => {
        fetchMSMEDetails();
    }, [fetchMSMEDetails]);

    useEffect(() => {
        const billingPlan = viewData?.billingPlan;
        if (!billingPlan) {
            return;
        }
        setBillingPlanId(billingPlan.selectedPlanId || 'msme_scale_yearly');
        setBillingPaidUntil(
            billingPlan.paidUntil
                ? new Date(billingPlan.paidUntil).toISOString().slice(0, 10)
                : ''
        );
        setBillingNote(billingPlan.adminOverrideNote || '');
    }, [viewData?.billingPlan]);

    const handleBillingPlanSave = async () => {
        if (!id) {
            return;
        }

        try {
            setBillingSaving(true);
            await axios.patch(
                buildApiUrl(`/admin/msme/${id}/billing-plan`),
                {
                    selectedPlanId: billingPlanId,
                    paidUntil: billingPaidUntil || undefined,
                    status: 'paid',
                    note: billingNote || undefined,
                },
                { headers: { Authorization: `Bearer ${getToken()}` } },
            );
            notifySuccess('Subscription plan updated for this user.');
            await fetchMSMEDetails();
        } catch (updateError: unknown) {
            const message = axios.isAxiosError(updateError)
                ? updateError.response?.data?.message
                : null;
            notifyError(message || 'Failed to update subscription plan.');
        } finally {
            setBillingSaving(false);
        }
    };

    const handleStatusUpdate = async (status: MsmeRegistryStatus, note: string) => {
        if (!id) {
            return;
        }

        try {
            setStatusSaving(true);
            await axios.put(
                buildApiUrl(`/admin/msme/${id}/status`),
                { status, note: note || undefined },
                { headers: { Authorization: `Bearer ${getToken()}` } },
            );
            setStatusDialogOpen(false);
            notifySuccess(`Status updated to ${status}.`);
            await fetchMSMEDetails();
        } catch (updateError: unknown) {
            const message = axios.isAxiosError(updateError)
                ? updateError.response?.data?.message
                : null;
            notifyError(message || 'Failed to update MSME status.');
        } finally {
            setStatusSaving(false);
        }
    };

    const handleExportAudit = () => {
        if (!msme) {
            return;
        }

        exportMsmeAuditCsv(msme.companyName, [
            { field: 'Company', value: msme.companyName },
            { field: 'Industry', value: msme.industry },
            { field: 'Status', value: msme.status },
            { field: 'GST', value: msme.gstNumber },
            { field: 'PAN', value: msme.panNumber },
            { field: 'Contact email', value: msme.contact?.email },
            { field: 'Total CO2 (kgCO2e)', value: viewData?.carbonEmissions?.totalCO2Emissions },
            { field: 'Carbon score', value: viewData?.carbonScore?.current },
            { field: 'Assessment status', value: viewData?.carbonEmissions?.assessmentStatus },
            { field: 'Recommendations total', value: viewData?.recommendations?.total },
            { field: 'Exported at', value: new Date().toISOString() },
        ]);
        notifySuccess('Audit summary downloaded as CSV.');
    };

    const getStatusColor = (status: string) => {
        switch (status) {
            case 'verified':
                return 'success';
            case 'flagged':
                return 'warning';
            case 'suspended':
                return 'error';
            default:
                return 'default';
        }
    };

    const getStatusIcon = (status: string) => {
        switch (status) {
            case 'verified':
                return <CheckCircle />;
            case 'flagged':
                return <Warning />;
            case 'suspended':
                return <Block />;
            default:
                return <Flag />;
        }
    };

    const scopeRows = useMemo(() => ([
        {
            name: 'Scope 1',
            total: viewData?.carbonEmissions?.esgScopes?.scope1?.total,
            percentage: viewData?.carbonEmissions?.esgScopes?.scope1?.percentage,
        },
        {
            name: 'Scope 2',
            total: viewData?.carbonEmissions?.esgScopes?.scope2?.total,
            percentage: viewData?.carbonEmissions?.esgScopes?.scope2?.percentage,
        },
        {
            name: 'Scope 3',
            total: viewData?.carbonEmissions?.esgScopes?.scope3?.total,
            percentage: viewData?.carbonEmissions?.esgScopes?.scope3?.percentage,
        },
    ]), [viewData]);

    const recommendationStatusSummary = Object.entries(viewData?.recommendations?.byStatus || {});
    const recommendationItems = viewData?.recommendations?.items || [];
    const benefitsRecentActivities = viewData?.benefits?.recentActivities || [];
    const scoreBreakdown = Object.entries(viewData?.carbonScore?.scoreBreakdown || {});
    const billsUploaded = viewData?.billsUploaded || [];
    const transactionsStored = useMemo(
      () => viewData?.transactionsStored || [],
      [viewData?.transactionsStored]
    );
    const profile = viewData?.profile;
    const operations = viewData?.operations;
    const reporting = viewData?.reporting;

    const adminScope1Kg = Number(viewData?.carbonEmissions?.esgScopes?.scope1?.total) || 0;
    const adminScope2Kg = Number(viewData?.carbonEmissions?.esgScopes?.scope2?.total) || 0;
    const adminScope3Kg = Number(viewData?.carbonEmissions?.esgScopes?.scope3?.total) || 0;
    const adminTotalKg = Number(viewData?.carbonEmissions?.totalCO2Emissions)
      || (adminScope1Kg + adminScope2Kg + adminScope3Kg);

    const adminTopSources = useMemo(() => {
      const fromTx = transactionsStored
        .map((tx) => ({
          name: tx.category || tx.description || 'Transaction',
          kg: Number(tx.carbonFootprint?.co2Emissions) || 0,
        }))
        .filter((row) => row.kg > 0)
        .sort((a, b) => b.kg - a.kg)
        .slice(0, 3);
      if (fromTx.length > 0) return fromTx;
      return scopeRows
        .filter((row) => Number(row.total) > 0)
        .map((row) => ({ name: row.name, kg: Number(row.total) || 0 }));
    }, [transactionsStored, scopeRows]);

    const adminMeasurementCompleteness = useMemo(() => {
      const energy = inferEnergySignals({
        categoryBreakdown: adminTopSources,
        scope1Kg: adminScope1Kg,
        scope2Kg: adminScope2Kg,
      });
      return deriveMeasurementCompleteness({
        hasProfile: Boolean(msme?.companyName && (msme?.gstNumber || profile?.companyName)),
        hasDocuments: billsUploaded.length > 0,
        hasAssessment: adminTotalKg > 0,
        hasWorkflow: Boolean(operations?.workflowLocked) || (Number(operations?.unitsCount) || 0) > 0,
        hasElectricitySignal: energy.hasElectricitySignal,
        hasFuelSignal: energy.hasFuelSignal,
        includeCta: false,
      });
    }, [
      adminTopSources,
      adminScope1Kg,
      adminScope2Kg,
      msme?.companyName,
      msme?.gstNumber,
      profile?.companyName,
      billsUploaded.length,
      adminTotalKg,
      operations?.workflowLocked,
      operations?.unitsCount,
    ]);
    const paymentSummary = !isViewRole ? viewData?.paymentSummary : null;
    const billingPlan = viewData?.billingPlan;

    if (loading) {
        return (
            <Box sx={{ display: 'flex', justifyContent: 'center', alignItems: 'center', minHeight: '80vh' }}>
                <CircularProgress />
            </Box>
        );
    }

    if (error || !msme) {
        return (
            <AdminPortalLayout title="MSME detail" maxWidth="lg">
                <Alert severity="error">{error || 'MSME not found'}</Alert>
                <Button
                    variant="contained"
                    startIcon={<ArrowBack />}
                    onClick={() => navigate('/admin/dashboard')}
                    sx={{ mt: 2 }}
                >
                    Back to registry
                </Button>
            </AdminPortalLayout>
        );
    }

    return (
        <AdminPortalLayout
            title={msme.companyName}
            subtitle="Workflow, emissions, and compliance snapshot for this MSME."
            maxWidth={false}
        >
                <Button
                    variant="outlined"
                    startIcon={<ArrowBack />}
                    onClick={() => navigate('/admin/dashboard')}
                    sx={{ mb: 3 }}
                >
                    Back to registry
                </Button>

                <Tabs
                    value={detailTab}
                    onChange={(_, value) => setDetailTab(value)}
                    sx={{ mb: 2 }}
                >
                    <Tab label="Evidence / assurance" />
                    <Tab label="Full registry detail" />
                </Tabs>

                {detailTab === 0 ? (
                    <Box sx={{ mb: 3 }}>
                        <AuditorEvidenceWorkspace
                            companyName={msme.companyName}
                            workspace={viewData?.evidenceWorkspace}
                            onExportCsv={handleExportAudit}
                        />
                    </Box>
                ) : null}

                {detailTab === 1 ? (
                <>
                <Paper sx={{ p: 3, mb: 3 }}>
                    <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', gap: 2, flexWrap: 'wrap' }}>
                        <Box>
                            <Typography variant="body2" color="text.secondary">
                                {isViewRole ? 'Read-only reviewer view' : 'Registry record'}
                            </Typography>
                            <Typography variant="subtitle1" sx={{ mt: 0.5 }}>
                                GST {msme.gstNumber || 'N/A'} · {msme.industry}
                            </Typography>
                        </Box>
                        <Stack direction="row" spacing={1} flexWrap="wrap" useFlexGap>
                            <Chip
                                icon={getStatusIcon(msme.status || 'pending')}
                                label={msme.status ? msme.status.charAt(0).toUpperCase() + msme.status.slice(1) : 'Pending'}
                                color={getStatusColor(msme.status || 'pending') as 'default' | 'success' | 'warning' | 'error'}
                                size="medium"
                            />
                            <Button
                                variant="outlined"
                                size="small"
                                startIcon={<Download />}
                                onClick={handleExportAudit}
                            >
                                Export audit CSV
                            </Button>
                            {!isViewRole && (
                                <Button
                                    variant="contained"
                                    size="small"
                                    startIcon={<Edit />}
                                    onClick={() => setStatusDialogOpen(true)}
                                >
                                    Update status
                                </Button>
                            )}
                        </Stack>
                    </Box>
                </Paper>

                {!isViewRole && (msme.adminNotes?.length ?? 0) > 0 && (
                    <Paper sx={{ p: 3, mb: 3 }}>
                        <Typography variant="h6" sx={{ fontWeight: 700, mb: 2 }}>
                            Admin notes
                        </Typography>
                        <Stack spacing={1.5}>
                            {(msme.adminNotes || []).map((entry, index) => {
                                const authorName = [
                                    entry.addedBy?.profile?.firstName,
                                    entry.addedBy?.profile?.lastName,
                                ]
                                    .filter(Boolean)
                                    .join(' ')
                                    .trim();
                                return (
                                    <Box
                                        key={`${entry.addedAt || index}`}
                                        sx={{
                                            p: 1.5,
                                            borderRadius: 1,
                                            bgcolor: 'action.hover',
                                        }}
                                    >
                                        <Typography variant="body2">{entry.note}</Typography>
                                        <Typography variant="caption" color="text.secondary">
                                            {authorName || entry.addedBy?.email || 'Administrator'}
                                            {entry.addedAt ? ` · ${formatDate(entry.addedAt)}` : ''}
                                        </Typography>
                                    </Box>
                                );
                            })}
                        </Stack>
                    </Paper>
                )}

                <MSMEStatusUpdateDialog
                    open={statusDialogOpen}
                    currentStatus={msme.status || 'pending'}
                    companyName={msme.companyName}
                    saving={statusSaving}
                    onClose={() => setStatusDialogOpen(false)}
                    onConfirm={handleStatusUpdate}
                />

                <MeasurementCompletenessRing
                    completeness={adminMeasurementCompleteness}
                    title="MSME measurement progress"
                    interactive={false}
                />

                <FootprintStoryPanel
                    title="MSME footprint story"
                    totalKg={adminTotalKg}
                    scope1Kg={adminScope1Kg}
                    scope2Kg={adminScope2Kg}
                    scope3Kg={adminScope3Kg}
                    topSources={adminTopSources}
                    summary="Read-only operator view of this MSME’s latest Scope 1–3 picture."
                    emptySummary="No assessment emissions recorded for this MSME yet."
                />

                {/* 1. Carbon Emissions */}
                <Paper sx={{ p: 3, mb: 3 }}>
                    <Typography variant="h6" sx={{ fontWeight: 700, mb: 2 }}>
                        1. Carbon Emissions
                    </Typography>
                    <Grid container spacing={2} sx={{ mb: 2 }}>
                        <Grid item xs={12} md={3}>
                            <Typography variant="body2" color="text.secondary">Total CO2 Emissions</Typography>
                            <Typography variant="h6">{formatNumber(viewData?.carbonEmissions?.totalCO2Emissions)} kgCO2e</Typography>
                        </Grid>
                        <Grid item xs={12} md={3}>
                            <Typography variant="body2" color="text.secondary">Assessment Type</Typography>
                            <Typography variant="body1">{viewData?.carbonEmissions?.assessmentType || 'N/A'}</Typography>
                        </Grid>
                        <Grid item xs={12} md={3}>
                            <Typography variant="body2" color="text.secondary">Assessment Status</Typography>
                            <Typography variant="body1">{viewData?.carbonEmissions?.assessmentStatus || 'N/A'}</Typography>
                        </Grid>
                        <Grid item xs={12} md={3}>
                            <Typography variant="body2" color="text.secondary">Last Updated</Typography>
                            <Typography variant="body1">{formatDate(viewData?.carbonEmissions?.updatedAt)}</Typography>
                        </Grid>
                    </Grid>
                    <TableContainer component={Paper} variant="outlined">
                        <Table size="small">
                            <TableHead>
                                <TableRow>
                                    <TableCell><strong>Scope</strong></TableCell>
                                    <TableCell><strong>Emissions (kgCO2e)</strong></TableCell>
                                    <TableCell><strong>Share (%)</strong></TableCell>
                                </TableRow>
                            </TableHead>
                            <TableBody>
                                {scopeRows.map((scope) => (
                                    <TableRow key={scope.name}>
                                        <TableCell>{scope.name}</TableCell>
                                        <TableCell>{formatNumber(scope.total)}</TableCell>
                                        <TableCell>{formatNumber(scope.percentage)}</TableCell>
                                    </TableRow>
                                ))}
                            </TableBody>
                        </Table>
                    </TableContainer>
                </Paper>

                {/* 2. Recommendations */}
                <Paper sx={{ p: 3, mb: 3 }}>
                    <Typography variant="h6" sx={{ fontWeight: 700, mb: 2 }}>
                        2. Recommendations
                    </Typography>
                    <Stack direction="row" spacing={1} flexWrap="wrap" sx={{ mb: 2 }}>
                        <Chip label={`Total: ${viewData?.recommendations?.total ?? 0}`} size="small" />
                        {recommendationStatusSummary.map(([statusKey, statusCount]) => (
                            <Chip key={statusKey} label={`${statusKey}: ${statusCount}`} size="small" />
                        ))}
                    </Stack>
                    {recommendationItems.length === 0 ? (
                        <Typography variant="body2" color="text.secondary">No recommendations available.</Typography>
                    ) : (
                        <TableContainer component={Paper} variant="outlined">
                            <Table size="small">
                                <TableHead>
                                    <TableRow>
                                        <TableCell><strong>Title</strong></TableCell>
                                        <TableCell><strong>Category</strong></TableCell>
                                        <TableCell><strong>Priority</strong></TableCell>
                                        <TableCell><strong>Status</strong></TableCell>
                                        <TableCell><strong>Potential Reduction</strong></TableCell>
                                    </TableRow>
                                </TableHead>
                                <TableBody>
                                    {recommendationItems.slice(0, 10).map((item) => (
                                        <TableRow key={item._id}>
                                            <TableCell>{item.title || 'N/A'}</TableCell>
                                            <TableCell>{item.category || 'N/A'}</TableCell>
                                            <TableCell>
                                                <Chip
                                                    label={item.priority || 'N/A'}
                                                    color={getPriorityColor(item.priority) as any}
                                                    size="small"
                                                />
                                            </TableCell>
                                            <TableCell>
                                                <Chip
                                                    label={item.status || 'N/A'}
                                                    color={getRecommendationStatusColor(item.status) as any}
                                                    size="small"
                                                />
                                            </TableCell>
                                            <TableCell>{formatNumber(item.potentialCO2Reduction)} kgCO2e</TableCell>
                                        </TableRow>
                                    ))}
                                </TableBody>
                            </Table>
                        </TableContainer>
                    )}
                </Paper>

                {/* 3. Carbon Score */}
                <Paper sx={{ p: 3, mb: 3 }}>
                    <Typography variant="h6" sx={{ fontWeight: 700, mb: 2 }}>
                        3. Carbon Score
                    </Typography>
                    <Grid container spacing={2} sx={{ mb: 2 }}>
                        <Grid item xs={12} md={3}>
                            <Typography variant="body2" color="text.secondary">Current Score</Typography>
                            <Typography variant="h5">{formatNumber(viewData?.carbonScore?.current ?? msme.carbonScore ?? 0)}</Typography>
                        </Grid>
                        <Grid item xs={12} md={3}>
                            <Typography variant="body2" color="text.secondary">Previous Score</Typography>
                            <Typography variant="body1">{formatNumber(viewData?.carbonScore?.previous)}</Typography>
                        </Grid>
                        <Grid item xs={12} md={3}>
                            <Typography variant="body2" color="text.secondary">Industry Average</Typography>
                            <Typography variant="body1">{formatNumber(viewData?.carbonScore?.industryAverage)}</Typography>
                        </Grid>
                        <Grid item xs={12} md={3}>
                            <Typography variant="body2" color="text.secondary">Best in Class</Typography>
                            <Typography variant="body1">{formatNumber(viewData?.carbonScore?.bestInClass)}</Typography>
                        </Grid>
                    </Grid>
                    {scoreBreakdown.length > 0 ? (
                        <Grid container spacing={2}>
                            {scoreBreakdown.map(([key, value]) => (
                                <Grid item xs={12} sm={6} md={4} key={key}>
                                    <Typography variant="body2" color="text.secondary">
                                        {key}
                                    </Typography>
                                    <Typography variant="body1" sx={{ fontWeight: 500 }}>
                                        {formatNumber(value)}
                                    </Typography>
                                </Grid>
                            ))}
                        </Grid>
                    ) : (
                        <Typography variant="body2" color="text.secondary">No score breakdown available.</Typography>
                    )}
                </Paper>

                {/* 4. Benefits */}
                <Paper sx={{ p: 3, mb: 3 }}>
                    <Typography variant="h6" sx={{ fontWeight: 700, mb: 2 }}>
                        4. Benefits
                    </Typography>
                    <Grid container spacing={2} sx={{ mb: 2 }}>
                        <Grid item xs={12} sm={6} md={2}>
                            <Typography variant="body2" color="text.secondary">Total Points</Typography>
                            <Typography variant="body1" sx={{ fontWeight: 500 }}>{formatNumber(viewData?.benefits?.totalPoints, 0)}</Typography>
                        </Grid>
                        <Grid item xs={12} sm={6} md={2}>
                            <Typography variant="body2" color="text.secondary">Level</Typography>
                            <Typography variant="body1" sx={{ fontWeight: 500 }}>{formatNumber(viewData?.benefits?.level, 0)}</Typography>
                        </Grid>
                        <Grid item xs={12} sm={6} md={2}>
                            <Typography variant="body2" color="text.secondary">Next Level Points</Typography>
                            <Typography variant="body1" sx={{ fontWeight: 500 }}>{formatNumber(viewData?.benefits?.nextLevelPoints, 0)}</Typography>
                        </Grid>
                        <Grid item xs={12} sm={6} md={2}>
                            <Typography variant="body2" color="text.secondary">Achievements</Typography>
                            <Typography variant="body1" sx={{ fontWeight: 500 }}>{formatNumber(viewData?.benefits?.achievementsUnlocked, 0)}</Typography>
                        </Grid>
                        <Grid item xs={12} sm={6} md={2}>
                            <Typography variant="body2" color="text.secondary">Carbon Saved</Typography>
                            <Typography variant="body1" sx={{ fontWeight: 500 }}>{formatNumber(viewData?.benefits?.carbonSaved)} kgCO2e</Typography>
                        </Grid>
                        <Grid item xs={12} sm={6} md={2}>
                            <Typography variant="body2" color="text.secondary">Streak</Typography>
                            <Typography variant="body1" sx={{ fontWeight: 500 }}>{formatNumber(viewData?.benefits?.streak, 0)}</Typography>
                        </Grid>
                    </Grid>
                    <Typography variant="subtitle2" sx={{ mb: 1 }}>Recent Activities</Typography>
                    {benefitsRecentActivities.length === 0 ? (
                        <Typography variant="body2" color="text.secondary">No recent benefit activity.</Typography>
                    ) : (
                        <Stack spacing={1}>
                            {benefitsRecentActivities.slice(0, 5).map((activity, index) => (
                                <Box key={`${activity.title}-${index}`} sx={{ p: 1.5, border: '1px solid', borderColor: 'divider', borderRadius: 1 }}>
                                    <Typography variant="body2" sx={{ fontWeight: 600 }}>
                                        {activity.title || 'Activity'}
                                    </Typography>
                                    <Typography variant="caption" color="text.secondary">
                                        {activity.description || 'No description'} | Points: {formatNumber(activity.points, 0)} | {formatDate(activity.createdAt)}
                                    </Typography>
                                </Box>
                            ))}
                        </Stack>
                    )}
                </Paper>

                {/* 5. Profile */}
                <Paper sx={{ p: 3, mb: 3 }}>
                    <Typography variant="h6" sx={{ fontWeight: 700, mb: 2 }}>
                        5. Profile
                    </Typography>
                    <Grid container spacing={2}>
                        <Grid item xs={12} md={4}>
                            <Typography variant="body2" color="text.secondary">Company Name</Typography>
                            <Typography variant="body1">{profile?.companyName || msme.companyName}</Typography>
                        </Grid>
                        <Grid item xs={12} md={4}>
                            <Typography variant="body2" color="text.secondary">Company Type</Typography>
                            <Typography variant="body1">{profile?.companyType || msme.companyType || 'N/A'}</Typography>
                        </Grid>
                        <Grid item xs={12} md={4}>
                            <Typography variant="body2" color="text.secondary">Business Domain</Typography>
                            <Typography variant="body1">{profile?.businessDomain || msme.businessDomain || 'N/A'}</Typography>
                        </Grid>
                        <Grid item xs={12} md={4}>
                            <Typography variant="body2" color="text.secondary">Industry</Typography>
                            <Typography variant="body1">{profile?.industry || msme.industry || 'N/A'}</Typography>
                        </Grid>
                        <Grid item xs={12} md={4}>
                            <Typography variant="body2" color="text.secondary">Establishment Year</Typography>
                            <Typography variant="body1">{profile?.establishmentYear || msme.establishmentYear || 'N/A'}</Typography>
                        </Grid>
                        <Grid item xs={12} md={4}>
                            <Typography variant="body2" color="text.secondary">Registration Date</Typography>
                            <Typography variant="body1">{formatDate(msme.createdAt)}</Typography>
                        </Grid>
                        <Grid item xs={12} md={4}>
                            <Typography variant="body2" color="text.secondary">Contact Email</Typography>
                            <Typography variant="body1">{profile?.contact?.email || msme.contact?.email || 'N/A'}</Typography>
                        </Grid>
                        <Grid item xs={12} md={4}>
                            <Typography variant="body2" color="text.secondary">Contact Phone</Typography>
                            <Typography variant="body1">{profile?.contact?.phone || msme.contact?.phone || 'N/A'}</Typography>
                        </Grid>
                        <Grid item xs={12} md={4}>
                            <Typography variant="body2" color="text.secondary">Address</Typography>
                            <Typography variant="body1">{formatAddress(profile?.contact?.address || msme.contact?.address)}</Typography>
                        </Grid>
                        <Grid item xs={12} md={4}>
                            <Typography variant="body2" color="text.secondary">Environmental Clearance</Typography>
                            <Typography variant="body1">
                                {getBooleanLabel(profile?.compliance?.hasEnvironmentalClearance ?? msme.environmentalCompliance?.hasEnvironmentalClearance)}
                            </Typography>
                        </Grid>
                        <Grid item xs={12} md={4}>
                            <Typography variant="body2" color="text.secondary">Pollution Control Board</Typography>
                            <Typography variant="body1">
                                {getBooleanLabel(profile?.compliance?.hasPollutionControlBoard ?? msme.environmentalCompliance?.hasPollutionControlBoard)}
                            </Typography>
                        </Grid>
                        <Grid item xs={12} md={4}>
                            <Typography variant="body2" color="text.secondary">Waste Management</Typography>
                            <Typography variant="body1">
                                {getBooleanLabel(profile?.compliance?.hasWasteManagement ?? msme.environmentalCompliance?.hasWasteManagement)}
                            </Typography>
                        </Grid>
                        <Grid item xs={12} md={4}>
                            <Typography variant="body2" color="text.secondary">User Name</Typography>
                            <Typography variant="body1">
                                {profile?.user?.profile?.firstName || msme.userId?.profile?.firstName || ''} {profile?.user?.profile?.lastName || msme.userId?.profile?.lastName || ''}
                            </Typography>
                        </Grid>
                        <Grid item xs={12} md={4}>
                            <Typography variant="body2" color="text.secondary">User Email</Typography>
                            <Typography variant="body1">{profile?.user?.email || msme.userId?.email || 'N/A'}</Typography>
                        </Grid>
                        <Grid item xs={12} md={4}>
                            <Typography variant="body2" color="text.secondary">Account Active</Typography>
                            <Typography variant="body1">{getBooleanLabel(profile?.user?.isActive ?? msme.userId?.isActive)}</Typography>
                        </Grid>
                    </Grid>
                </Paper>

                {/* 6. Operations */}
                <Paper sx={{ p: 3, mb: 3 }}>
                    <Typography variant="h6" sx={{ fontWeight: 700, mb: 2 }}>
                        6. Operations
                    </Typography>
                    <Grid container spacing={2} sx={{ mb: 2 }}>
                        <Grid item xs={12} sm={6} md={2}>
                            <Typography variant="body2" color="text.secondary">Units</Typography>
                            <Typography variant="body1" sx={{ fontWeight: 500 }}>{formatNumber(operations?.unitsCount, 0)}</Typography>
                        </Grid>
                        <Grid item xs={12} sm={6} md={2}>
                            <Typography variant="body2" color="text.secondary">Processes</Typography>
                            <Typography variant="body1" sx={{ fontWeight: 500 }}>{formatNumber(operations?.processesCount, 0)}</Typography>
                        </Grid>
                        <Grid item xs={12} sm={6} md={2}>
                            <Typography variant="body2" color="text.secondary">Employees</Typography>
                            <Typography variant="body1" sx={{ fontWeight: 500 }}>{formatNumber(operations?.employeesCount, 0)}</Typography>
                        </Grid>
                        <Grid item xs={12} sm={6} md={3}>
                            <Typography variant="body2" color="text.secondary">Supply Chain Partners</Typography>
                            <Typography variant="body1" sx={{ fontWeight: 500 }}>{formatNumber(operations?.supplyChainPartnersCount, 0)}</Typography>
                        </Grid>
                        <Grid item xs={12} sm={6} md={3}>
                            <Typography variant="body2" color="text.secondary">Workflow Locked</Typography>
                            <Typography variant="body1" sx={{ fontWeight: 500 }}>{operations?.workflowLocked ? 'Yes' : 'No'}</Typography>
                        </Grid>
                    </Grid>
                    <TableContainer component={Paper} variant="outlined">
                        <Table size="small">
                            <TableHead>
                                <TableRow>
                                    <TableCell><strong>Metric</strong></TableCell>
                                    <TableCell><strong>Value (kgCO2e)</strong></TableCell>
                                </TableRow>
                            </TableHead>
                            <TableBody>
                                <TableRow>
                                    <TableCell>Total CO2 Emissions</TableCell>
                                    <TableCell>{formatNumber(operations?.latestEstimate?.totalCO2Emissions)}</TableCell>
                                </TableRow>
                                <TableRow>
                                    <TableCell>Machinery Emissions</TableCell>
                                    <TableCell>{formatNumber(operations?.latestEstimate?.machineryEmissions)}</TableCell>
                                </TableRow>
                                <TableRow>
                                    <TableCell>Raw Material Emissions</TableCell>
                                    <TableCell>{formatNumber(operations?.latestEstimate?.rawMaterialEmissions)}</TableCell>
                                </TableRow>
                                <TableRow>
                                    <TableCell>Packaging Emissions</TableCell>
                                    <TableCell>{formatNumber(operations?.latestEstimate?.packagingMaterialEmissions)}</TableCell>
                                </TableRow>
                                <TableRow>
                                    <TableCell>Commute Emissions</TableCell>
                                    <TableCell>{formatNumber(operations?.latestEstimate?.commuteEmissions)}</TableCell>
                                </TableRow>
                                <TableRow>
                                    <TableCell>Supply Chain Emissions</TableCell>
                                    <TableCell>{formatNumber(operations?.latestEstimate?.supplyChainEmissions)}</TableCell>
                                </TableRow>
                                <TableRow>
                                    <TableCell>Scope 3 Emissions</TableCell>
                                    <TableCell>{formatNumber(operations?.latestEstimate?.scope3Emissions)}</TableCell>
                                </TableRow>
                            </TableBody>
                        </Table>
                    </TableContainer>
                    <Typography variant="caption" color="text.secondary" sx={{ mt: 1, display: 'block' }}>
                        Last estimated at: {formatDate(operations?.lastEstimatedAt)}
                    </Typography>
                </Paper>

                {/* 7. Reporting */}
                <Paper sx={{ p: 3, mb: 3 }}>
                    <Typography variant="h6" sx={{ fontWeight: 700, mb: 2 }}>
                        7. Reporting
                    </Typography>
                    <Grid container spacing={2} sx={{ mb: 2 }}>
                        <Grid item xs={12} md={4}>
                            <Typography variant="body2" color="text.secondary">Available Reports</Typography>
                            <Typography variant="body1" sx={{ fontWeight: 500 }}>
                                {formatNumber(reporting?.availableReports, 0)}
                            </Typography>
                        </Grid>
                        <Grid item xs={12} md={4}>
                            <Typography variant="body2" color="text.secondary">Latest Assessment</Typography>
                            <Typography variant="body1" sx={{ fontWeight: 500 }}>
                                {formatDate(reporting?.latestAssessmentDate || undefined)}
                            </Typography>
                        </Grid>
                        <Grid item xs={12} md={4}>
                            <Typography variant="body2" color="text.secondary">Report Context</Typography>
                            <Typography variant="body1" sx={{ fontWeight: 500 }}>
                                {reporting?.latestReportContext || 'N/A'}
                            </Typography>
                        </Grid>
                    </Grid>
                    <TableContainer component={Paper} variant="outlined">
                        <Table size="small">
                            <TableHead>
                                <TableRow>
                                    <TableCell><strong>Report</strong></TableCell>
                                    <TableCell><strong>Endpoint</strong></TableCell>
                                    <TableCell><strong>Status</strong></TableCell>
                                    <TableCell><strong>Description</strong></TableCell>
                                </TableRow>
                            </TableHead>
                            <TableBody>
                                {(reporting?.endpoints || []).map((reportItem) => (
                                    <TableRow key={reportItem.key}>
                                        <TableCell>{reportItem.label}</TableCell>
                                        <TableCell>{reportItem.endpoint}</TableCell>
                                        <TableCell>
                                            <Chip
                                                label={reportItem.available ? 'Available' : 'Pending'}
                                                size="small"
                                                color={reportItem.available ? 'success' : 'default'}
                                            />
                                        </TableCell>
                                        <TableCell>{reportItem.description}</TableCell>
                                    </TableRow>
                                ))}
                            </TableBody>
                        </Table>
                    </TableContainer>
                </Paper>

                {/* 8. Bills Uploaded */}
                <Paper sx={{ p: 3, mb: 3 }}>
                    <Typography variant="h6" sx={{ fontWeight: 700, mb: 2 }}>
                        8. Bills Uploaded
                    </Typography>
                    {billsUploaded.length === 0 ? (
                        <Typography variant="body2" color="text.secondary">No uploaded bills found.</Typography>
                    ) : (
                        <TableContainer component={Paper} variant="outlined">
                            <Table size="small">
                                <TableHead>
                                    <TableRow>
                                        <TableCell><strong>File</strong></TableCell>
                                        <TableCell><strong>Type</strong></TableCell>
                                        <TableCell><strong>Status</strong></TableCell>
                                        <TableCell><strong>Amount</strong></TableCell>
                                        <TableCell><strong>Bill Date</strong></TableCell>
                                        <TableCell><strong>Uploaded</strong></TableCell>
                                    </TableRow>
                                </TableHead>
                                <TableBody>
                                    {billsUploaded.map((bill) => (
                                        <TableRow key={bill._id}>
                                            <TableCell>{bill.originalName || bill.fileName || 'N/A'}</TableCell>
                                            <TableCell>{bill.documentType || 'N/A'}</TableCell>
                                            <TableCell>
                                                <Chip label={bill.status || 'N/A'} size="small" />
                                            </TableCell>
                                            <TableCell>{formatCurrency(bill.extractedData?.amount)}</TableCell>
                                            <TableCell>{formatDate(bill.extractedData?.date)}</TableCell>
                                            <TableCell>{formatDate(bill.createdAt)}</TableCell>
                                        </TableRow>
                                    ))}
                                </TableBody>
                            </Table>
                        </TableContainer>
                    )}
                </Paper>

                <Paper sx={{ p: 3, mb: 3 }}>
                    <Typography variant="h6" sx={{ fontWeight: 700, mb: 2 }}>
                        9. Subscription plan (gating)
                    </Typography>
                    <Grid container spacing={2} sx={{ mb: 2 }}>
                        <Grid item xs={12} md={3}>
                            <Typography variant="body2" color="text.secondary">Current plan</Typography>
                            <Typography variant="body1" sx={{ fontWeight: 600 }}>
                                {formatPlanLabel(billingPlan?.selectedPlanId)}
                            </Typography>
                        </Grid>
                        <Grid item xs={12} md={3}>
                            <Typography variant="body2" color="text.secondary">Effective tier</Typography>
                            <Typography variant="body1">{billingPlan?.effectiveTier || 'free'}</Typography>
                        </Grid>
                        <Grid item xs={12} md={3}>
                            <Typography variant="body2" color="text.secondary">Billing status</Typography>
                            <Typography variant="body1">{billingPlan?.status || 'none'}</Typography>
                        </Grid>
                        <Grid item xs={12} md={3}>
                            <Typography variant="body2" color="text.secondary">Paid until</Typography>
                            <Typography variant="body1">{formatDate(billingPlan?.paidUntil || undefined)}</Typography>
                        </Grid>
                        {billingPlan?.adminOverrideAt ? (
                            <Grid item xs={12}>
                                <Typography variant="caption" color="text.secondary">
                                    Last admin override: {formatDate(billingPlan.adminOverrideAt)}
                                    {billingPlan.adminOverrideNote ? ` · ${billingPlan.adminOverrideNote}` : ''}
                                </Typography>
                            </Grid>
                        ) : null}
                    </Grid>
                    {!isViewRole ? (
                        <Stack spacing={2} sx={{ maxWidth: 720 }}>
                            <FormControl fullWidth size="small">
                                <InputLabel id="admin-billing-plan-label">Assign plan</InputLabel>
                                <Select
                                    labelId="admin-billing-plan-label"
                                    label="Assign plan"
                                    value={billingPlanId}
                                    onChange={(event) => setBillingPlanId(event.target.value)}
                                >
                                    {ADMIN_ASSIGNABLE_PLANS.map((plan) => (
                                        <MenuItem key={plan.planId} value={plan.planId}>
                                            {plan.name} ({plan.interval})
                                        </MenuItem>
                                    ))}
                                </Select>
                            </FormControl>
                            <TextField
                                label="Paid until"
                                type="date"
                                size="small"
                                value={billingPaidUntil}
                                onChange={(event) => setBillingPaidUntil(event.target.value)}
                                InputLabelProps={{ shrink: true }}
                                helperText="Leave blank to default to one year from today."
                            />
                            <TextField
                                label="Override note (optional)"
                                size="small"
                                value={billingNote}
                                onChange={(event) => setBillingNote(event.target.value)}
                                multiline
                                minRows={2}
                            />
                            <Box>
                                <Button
                                    variant="contained"
                                    onClick={handleBillingPlanSave}
                                    disabled={billingSaving}
                                >
                                    {billingSaving ? 'Saving…' : 'Save plan override'}
                                </Button>
                            </Box>
                        </Stack>
                    ) : (
                        <Typography variant="body2" color="text.secondary">
                            Reviewer view — plan assignment is read-only.
                        </Typography>
                    )}
                </Paper>

                {!isViewRole && (
                    <Paper sx={{ p: 3, mb: 3 }}>
                        <Typography variant="h6" sx={{ fontWeight: 700, mb: 2 }}>
                            10. Payment Summary
                        </Typography>
                        {!paymentSummary ? (
                            <Typography variant="body2" color="text.secondary">
                                Payment summary not available.
                            </Typography>
                        ) : (
                            <>
                                <Grid container spacing={2} sx={{ mb: 2 }}>
                                    <Grid item xs={12} md={4}>
                                        <Typography variant="body2" color="text.secondary">Payment Amount</Typography>
                                        <Typography variant="h6">
                                            {formatCurrencyWithFraction(
                                                paymentSummary.paymentAmount,
                                                paymentSummary.currency || 'INR'
                                            )}
                                        </Typography>
                                    </Grid>
                                    <Grid item xs={12} md={4}>
                                        <Typography variant="body2" color="text.secondary">Sector</Typography>
                                        <Typography variant="body1">{paymentSummary.factors?.sector || 'N/A'}</Typography>
                                    </Grid>
                                    <Grid item xs={12} md={4}>
                                        <Typography variant="body2" color="text.secondary">Emission Intensity</Typography>
                                        <Typography variant="body1">
                                            {formatNumber(paymentSummary.factors?.emissionIntensity, 3)}
                                        </Typography>
                                    </Grid>
                                </Grid>
                                <TableContainer component={Paper} variant="outlined">
                                    <Table size="small">
                                        <TableHead>
                                            <TableRow>
                                                <TableCell><strong>Factor</strong></TableCell>
                                                <TableCell><strong>Value</strong></TableCell>
                                                <TableCell><strong>Charge</strong></TableCell>
                                            </TableRow>
                                        </TableHead>
                                        <TableBody>
                                            <TableRow>
                                                <TableCell>Transactions</TableCell>
                                                <TableCell>{formatNumber(paymentSummary.factors?.transactionCount, 0)}</TableCell>
                                                <TableCell>{formatCurrencyWithFraction(paymentSummary.breakdown?.transactionVolumeCharge, paymentSummary.currency || 'INR')}</TableCell>
                                            </TableRow>
                                            <TableRow>
                                                <TableCell>Processes</TableCell>
                                                <TableCell>{formatNumber(paymentSummary.factors?.processCount, 0)}</TableCell>
                                                <TableCell>{formatCurrencyWithFraction(paymentSummary.breakdown?.processCharge, paymentSummary.currency || 'INR')}</TableCell>
                                            </TableRow>
                                            <TableRow>
                                                <TableCell>Raw Materials</TableCell>
                                                <TableCell>{formatNumber(paymentSummary.factors?.rawMaterialCount, 0)}</TableCell>
                                                <TableCell>{formatCurrencyWithFraction(paymentSummary.breakdown?.rawMaterialCharge, paymentSummary.currency || 'INR')}</TableCell>
                                            </TableRow>
                                            <TableRow>
                                                <TableCell>Machinery Deployed</TableCell>
                                                <TableCell>{formatNumber(paymentSummary.factors?.machineryCount, 0)}</TableCell>
                                                <TableCell>{formatCurrencyWithFraction(paymentSummary.breakdown?.machineryCharge, paymentSummary.currency || 'INR')}</TableCell>
                                            </TableRow>
                                            <TableRow>
                                                <TableCell>Sites</TableCell>
                                                <TableCell>{formatNumber(paymentSummary.factors?.siteCount, 0)}</TableCell>
                                                <TableCell>{formatCurrencyWithFraction(paymentSummary.breakdown?.siteCharge, paymentSummary.currency || 'INR')}</TableCell>
                                            </TableRow>
                                            <TableRow>
                                                <TableCell>Emission Intensity Adjustment</TableCell>
                                                <TableCell>{formatNumber(paymentSummary.factors?.emissionIntensity, 3)}</TableCell>
                                                <TableCell>{formatCurrencyWithFraction(paymentSummary.breakdown?.emissionIntensityCharge, paymentSummary.currency || 'INR')}</TableCell>
                                            </TableRow>
                                            <TableRow>
                                                <TableCell>Base Amount</TableCell>
                                                <TableCell>Fixed</TableCell>
                                                <TableCell>{formatCurrencyWithFraction(paymentSummary.breakdown?.baseAmount, paymentSummary.currency || 'INR')}</TableCell>
                                            </TableRow>
                                        </TableBody>
                                    </Table>
                                </TableContainer>
                            </>
                        )}
                    </Paper>
                )}

                {/* 10. Transactions Stored */}
                <Paper sx={{ p: 3 }}>
                    <Typography variant="h6" sx={{ fontWeight: 700, mb: 2 }}>
                        {!isViewRole ? '11. Transactions Stored' : '10. Transactions Stored'}
                    </Typography>
                    {transactionsStored.length === 0 ? (
                        <Typography variant="body2" color="text.secondary">No transactions available.</Typography>
                    ) : (
                        <TableContainer component={Paper} variant="outlined">
                            <Table size="small">
                                <TableHead>
                                    <TableRow>
                                        <TableCell><strong>Description</strong></TableCell>
                                        <TableCell><strong>Category</strong></TableCell>
                                        <TableCell><strong>Source</strong></TableCell>
                                        <TableCell><strong>Amount</strong></TableCell>
                                        <TableCell><strong>CO2</strong></TableCell>
                                        <TableCell><strong>Date</strong></TableCell>
                                    </TableRow>
                                </TableHead>
                                <TableBody>
                                    {transactionsStored.map((transaction) => (
                                        <TableRow key={transaction._id}>
                                            <TableCell>{transaction.description || 'N/A'}</TableCell>
                                            <TableCell>{transaction.category || 'N/A'}</TableCell>
                                            <TableCell>{transaction.source || 'N/A'}</TableCell>
                                            <TableCell>{formatCurrency(transaction.amount, transaction.currency || 'INR')}</TableCell>
                                            <TableCell>{formatNumber(transaction.carbonFootprint?.co2Emissions)} kgCO2e</TableCell>
                                            <TableCell>{formatDate(transaction.date)}</TableCell>
                                        </TableRow>
                                    ))}
                                </TableBody>
                            </Table>
                        </TableContainer>
                    )}
                </Paper>
                </>
                ) : null}
        </AdminPortalLayout>
    );
};

export default MSMEDetailView;
